code.cpp:
class Solution {
public:
    int calculateScore(int a, int b) {
        int s1 = __builtin_popcount(static_cast<unsigned>(a));
        int s2 = __builtin_popcount(static_cast<unsigned>(b));
        if (s1 >= s2) {
            return s1 * s2;
        }
        return s2 / s1;
    }
};
